import fs from 'fs';
import path from 'path';

const directoryPath = './data/';

try {
  const files = fs.readdirSync(directoryPath);
  const txtFiles = files.filter(file => file.endsWith('.txt'));

  txtFiles.forEach(file => {
    const filePath = path.join(directoryPath, file);
    const content = fs.readFileSync(filePath);

    // Convert from Shift_JIS to UTF-8
    // Using iconv-lite would be more robust, but since I don't know if it's installed,
    // I'll try to use Buffer.from with 'shift_jis' if supported, 
    // or just assume the environment can handle it via a simple script.
    // Actually, Node.js doesn't support Shift_JIS natively in Buffer.from.
    // I will use a python script instead as it has better built-in support for encodings.
    console.log(`Processing ${file}`);
  });
} catch (err) {
  console.error('Error:', err);
}

